import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class ContractTest{@Test void arithmeticNewValuesAndPreservedOperands(){long[][]expected={{5,6},{1,6},{1,6},{3,2}};for(int op=0;op<4;op++){Object a=TaskBinding.value(1,2),b=TaskBinding.value(1,3);Object result=TaskBinding.operation(a,b,op);assertArrayEquals(expected[op],TaskBinding.parts(result));assertNotSame(a,result);assertNotSame(b,result);assertArrayEquals(new long[]{1,2},TaskBinding.parts(a));assertArrayEquals(new long[]{1,3},TaskBinding.parts(b));}Object a=TaskBinding.value(1,2),zero=TaskBinding.value(0,1);assertThrows(ArithmeticException.class,()->TaskBinding.operation(a,zero,3));assertArrayEquals(new long[]{1,2},TaskBinding.parts(a));assertArrayEquals(new long[]{0,1},TaskBinding.parts(zero));assertFalse(TaskBinding.text(a).isBlank());assertNotEquals(TaskBinding.text(a),TaskBinding.text(TaskBinding.value(2,3)));}}
